//! The OSD exception classes declared by DEFINE_STANDARD_EXCEPTION, as typed
//! `Failure` constructors. Each keeps the native class name as its exception type.
//!
//! The constructors are written out one by one (not generated by a macro) so each body
//! is literally `Failure::with_type("<class>", message, "")`: the API ledger generator
//! proves the C++ constructors and `ExceptionType()` from that source shape.
use crate::standard::Failure;

/// Raises `OSD_Exception`, the base of the structured-exception (Windows SEH)
/// translations; `osd::exception("message")`.
pub fn exception(message: &str) -> Failure {
    Failure::with_type("OSD_Exception", message, "")
}

