/// `(class, direct base)` of every macro-generated OSD exception, in declaration order.
const HIERARCHY: [(&str, &str); 21] = [
    ("OSD_Exception", "Standard_Failure"),
    ("OSD_Exception_ACCESS_VIOLATION", "OSD_Exception"),
    ("OSD_Exception_ARRAY_BOUNDS_EXCEEDED", "OSD_Exception"),
    ("OSD_Exception_CTRL_BREAK", "OSD_Exception"),
    ("OSD_Exception_ILLEGAL_INSTRUCTION", "OSD_Exception"),
    ("OSD_Exception_IN_PAGE_ERROR", "OSD_Exception"),
    ("OSD_Exception_INT_OVERFLOW", "OSD_Exception"),
    ("OSD_Exception_INVALID_DISPOSITION", "OSD_Exception"),
    ("OSD_Exception_NONCONTINUABLE_EXCEPTION", "OSD_Exception"),
    ("OSD_Exception_PRIV_INSTRUCTION", "OSD_Exception"),
    ("OSD_Exception_STACK_OVERFLOW", "OSD_Exception"),
    ("OSD_Exception_STATUS_NO_MEMORY", "OSD_Exception"),
    ("OSD_Signal", "Standard_Failure"),
    ("OSD_SIGBUS", "OSD_Signal"),
    ("OSD_SIGHUP", "OSD_Signal"),
    ("OSD_SIGILL", "OSD_Signal"),
    ("OSD_SIGINT", "OSD_Signal"),
    ("OSD_SIGKILL", "OSD_Signal"),
    ("OSD_SIGQUIT", "OSD_Signal"),
    ("OSD_SIGSEGV", "OSD_Signal"),
    ("OSD_SIGSYS", "OSD_Signal"),
];

/// The class column of a hierarchy table, computed at compile time so the names are
/// written once; `class_names(HIERARCHY)[12] == "OSD_Signal"`.
const fn class_names<const N: usize>(
    pairs: [(&'static str, &'static str); N],
) -> [&'static str; N] {
    let mut names = [""; N];
    let mut index = 0;
    while index < N {
        names[index] = pairs[index].0;
        index += 1;
    }
    names
}

const TYPES: [&str; 21] = class_names(HIERARCHY);
/// Every OSD exception type name, in the order declared above.
pub const OSD_EXCEPTION_TYPES: &[&str] = &TYPES;
/// The direct native base class of every macro-generated OSD exception constructor.
pub(crate) const OSD_EXCEPTION_HIERARCHY: &[(&str, &str)] = &HIERARCHY;

/// Parent of the non-macro OSD_OSDError constructor; `exception_parent(OSD_OSD_ERROR_PARENT.0)`.
pub(crate) const OSD_OSD_ERROR_PARENT: (&str, &str) = ("OSD_OSDError", "Standard_Failure");

#[cfg(test)]
mod tests {
    use super::*;

    // Each constructor must build the class its table row names, in table order, so the
    // written-out functions and the hierarchy cannot drift apart.
    #[test]
    fn constructors_follow_the_hierarchy_table() {
        let constructors: [fn(&str) -> Failure; 21] = [
            exception,
            exception_access_violation,
            exception_array_bounds_exceeded,
            exception_ctrl_break,
            exception_illegal_instruction,
            exception_in_page_error,
            exception_int_overflow,
            exception_invalid_disposition,
            exception_noncontinuable_exception,
            exception_priv_instruction,
            exception_stack_overflow,
            exception_status_no_memory,
            signal,
            sigbus,
            sighup,
            sigill,
            sigint,
            sigkill,
            sigquit,
            sigsegv,
            sigsys,
        ];
        for (constructor, (class, _)) in constructors.iter().zip(HIERARCHY) {
            let failure = constructor("text");
            assert_eq!(failure.exception_type(), class);
            assert_eq!(failure.message(), "text");
        }
    }

    #[test]
    fn signals_are_caught_by_their_native_bases() {
        assert!(sigsegv("").is_kind("OSD_Signal"));
        assert!(exception_stack_overflow("").is_kind("OSD_Exception"));
        assert!(!sigsegv("").is_kind("OSD_Exception"));
    }
}
